class Solution {
  public int[] longestSpecialPath(int[][] edges, int[] nums) {
    int n = nums.length;
    int[] start = new int[n + 1];
    for (int[] e : edges) {
      start[e[0] + 1]++;
      start[e[1] + 1]++;
    }
    for (int i = 0; i < n; i++) start[i + 1] += start[i];
    int[] fill = new int[n], to = new int[2 * (n - 1)], w = new int[2 * (n - 1)];
    for (int[] e : edges) {
      int p = start[e[0]] + fill[e[0]]++;
      to[p] = e[1];
      w[p] = e[2];
      p = start[e[1]] + fill[e[1]]++;
      to[p] = e[0];
      w[p] = e[2];
    }
    int[] lastOcc = new int[50_001];
    java.util.Arrays.fill(lastOcc, -1);
    long[] dist = new long[n];
    int[] stNode = new int[n],
        stPar = new int[n],
        stPtr = new int[n],
        stOcc = new int[n],
        stTop = new int[n];
    int sp = 0, top = 0;
    long bestLen = 0;
    int bestNodes = 1;
    stNode[0] = 0;
    stPar[0] = -1;
    stPtr[0] = start[0];
    stOcc[0] = -1;
    stTop[0] = 0;
    lastOcc[nums[0]] = 0;
    sp = 1;
    while (sp > 0) {
      int d = sp - 1, u = stNode[d];
      if (stPtr[d] < start[u + 1]) {
        int p = stPtr[d]++;
        int v = to[p];
        if (v == stPar[d]) continue;
        int nd = d + 1;
        stNode[nd] = v;
        stPar[nd] = u;
        stPtr[nd] = start[v];
        stOcc[nd] = lastOcc[nums[v]];
        stTop[nd] = top;
        top = Math.max(top, stOcc[nd] + 1);
        lastOcc[nums[v]] = nd;
        dist[nd] = dist[d] + w[p];
        long len = dist[nd] - dist[top];
        int nodes = nd - top + 1;
        if (len > bestLen || (len == bestLen && nodes < bestNodes)) {
          bestLen = len;
          bestNodes = nodes;
        }
        sp++;
      } else {
        lastOcc[nums[u]] = stOcc[d];
        if (d > 0) top = stTop[d];
        sp--;
      }
    }
    return new int[] {(int) bestLen, bestNodes};
  }
}
